def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    opp_ops = [h[1] for h in history]
    opp_d = opp_ops.count('D')

    if n >= 20 and opp_d / n >= 0.3:
        return 'D'

    if opp_ops[-1] == 'D':
        return 'D'
    else:
        return 'C'
